=== hex_lowercase.ino ===
   1| // Lab 5 - student ID responder (Serial1, 9600 baud)
   2| //
   3| // All three answers are built once as Strings in setup(), then each
   4| // command just prints the matching String.
   5| //   ID  : "<student_id>"
   6| //   SUM : digits added together
   7| //   HEX : String(value, HEX) gives the hex digits with no leading zeros
   8| 
   9| const char ID_TEXT[] = "<student_id>";
  10| 
  11| String idReply, sumReply, hexReply;
  12| String pending;
  13| 
  14| void setup() {
  15|   Serial1.begin(9600);
  16| 
  17|   unsigned long idNum = 0;
  18|   int digits = 0;
  19|   for (int i = 0; ID_TEXT[i]; i++) {
  20|     int d = ID_TEXT[i] - '0';
  21|     digits += d;
  22|     idNum = idNum * 10 + d;
  23|   }
  24| 
  25|   idReply  = String(ID_TEXT);
  26|   sumReply = String(digits);
  27|   hexReply = String(idNum, HEX);
  28| }
  29| 
  30| void loop() {
  31|   while (Serial1.available()) {
  32|     char c = Serial1.read();
  33|     if (c == '\n') {
  34|       pending.trim();                 // drop '\r' and stray spaces
  35|       if (pending.length() > 0) {
  36|         if (pending == "ID?")        Serial1.println(idReply);
  37|         else if (pending == "SUM?")  Serial1.println(sumReply);
  38|         else if (pending == "HEX?")  Serial1.println(hexReply);
  39|         else                         Serial1.println("ERR");
  40|       }
  41|       pending = "";
  42|     } else {
  43|       pending += c;
  44|     }
  45|   }
  46| }
</student_code>
